import type * as THREE from 'three';
import type { Quat, Vec3 } from '../contracts/math';
import type { ObstacleDescriptor } from '../courses/types';

export const IDENTITY_ROTATION: Quat = { x: 0, y: 0, z: 0, w: 1 };
export const UNIT_SCALE: Vec3 = { x: 1, y: 1, z: 1 };

/** World transform an obstacle occupies at a point in time. */
export interface ObstaclePose {
  position: Vec3;
  rotation: Quat;
}

/** Collider parameters derived from a descriptor before any body exists. */
export interface ObstacleBodyOptions {
  /** Full box size; adapters halve it for half-extent based APIs. */
  size: Vec3;
  kinematic: boolean;
  sensor: boolean;
  friction: number;
  restitution: number;
}

/** Physics handle owned by a DynamicObstacle for its whole lifetime. */
export interface ObstacleBody {
  setPose(pose: ObstaclePose): void;
  setEnabled(enabled: boolean): void;
  dispose(): void;
}

/** Creates physics bodies; Rapier at runtime, a fake in tests, null when physics is off. */
export interface ObstaclePhysicsAdapter {
  createBody(
    descriptor: ObstacleDescriptor,
    pose: ObstaclePose,
    options: ObstacleBodyOptions,
  ): ObstacleBody | null;
}

export interface ObstacleVisualOptions {
  size: Vec3;
  sensor: boolean;
}

/** Creates the visual representation of an obstacle. */
export interface ObstacleVisualFactory {
  create(descriptor: ObstacleDescriptor, options: ObstacleVisualOptions): THREE.Object3D | null;
}
