import type { HazardObstacle, MovingObstacle, ObstacleDescriptor, StaticObstacle } from '../courses/types';

export const OBSTACLE_CONFIG = {
  /** Largest step a single update() may advance, so tab-out spikes cannot teleport obstacles. */
  maxUpdateStep: 0.1,
  friction: 0.4,
  hazardOpacity: 0.45,
  restitution: {
