    bumper: 0.92,
    pillar: 0.5,
    block: 0.4,
    spinner: 0.55,
    windmill: 0.5,
    gate: 0.4,
    platform: 0.3,
    water: 0,
    void: 0,
    'reset-zone': 0,
  },
  colors: {
    wall: 0xb9c4cf,
    bumper: 0xef6f5c,
    pillar: 0xa9926f,
    block: 0x8f9bb3,
    spinner: 0x6fc2d8,
    windmill: 0xe8c56a,
    gate: 0x9a7fd8,
    platform: 0x7fb069,
    water: 0x3f8fd0,
    void: 0x1b1b2b,
    'reset-zone': 0xd8637f,
  },
} as const;

export function isStaticObstacle(descriptor: ObstacleDescriptor): descriptor is StaticObstacle {
  return descriptor.type === 'wall' || descriptor.type === 'bumper' ||
    descriptor.type === 'pillar' || descriptor.type === 'block';
}

export function isMovingObstacle(descriptor: ObstacleDescriptor): descriptor is MovingObstacle {
  return descriptor.type === 'spinner' || descriptor.type === 'windmill' ||
    descriptor.type === 'gate' || descriptor.type === 'platform';
}

export function isHazardObstacle(descriptor: ObstacleDescriptor): descriptor is HazardObstacle {
  return descriptor.type === 'water' || descriptor.type === 'void' || descriptor.type === 'reset-zone';
}

export function obstacleRestitution(descriptor: ObstacleDescriptor): number {
  const override = isStaticObstacle(descriptor) ? descriptor.restitution : undefined;
  return override ?? OBSTACLE_CONFIG.restitution[descriptor.type];
}

export function obstacleColor(descriptor: ObstacleDescriptor): number {
  return OBSTACLE_CONFIG.colors[descriptor.type];
}
