import type { Quat, Vec3 } from '../contracts/math';
import type { MovingObstacle, ObstacleDescriptor } from '../courses/types';
import { IDENTITY_ROTATION, UNIT_SCALE, type ObstaclePose } from './types';

const DEFAULT_AXIS: Vec3 = { x: 0, y: 1, z: 0 };

export function normalizeAxis(axis: Vec3 | undefined): Vec3 {
  if (!axis) return { ...DEFAULT_AXIS };
  const length = Math.hypot(axis.x, axis.y, axis.z);
  if (!Number.isFinite(length) || length < 1e-8) return { ...DEFAULT_AXIS };
  return { x: axis.x / length, y: axis.y / length, z: axis.z / length };
}

export function quatFromAxisAngle(axis: Vec3, angle: number): Quat {
  const unit = normalizeAxis(axis);
  const half = angle * 0.5;
  const sin = Math.sin(half);
  return { x: unit.x * sin, y: unit.y * sin, z: unit.z * sin, w: Math.cos(half) };
}

export function multiplyQuat(a: Quat, b: Quat): Quat {
  return {
    x: a.w * b.x + a.x * b.w + a.y * b.z - a.z * b.y,
    y: a.w * b.y - a.x * b.z + a.y * b.w + a.z * b.x,
    z: a.w * b.z + a.x * b.y - a.y * b.x + a.z * b.w,
    w: a.w * b.w - a.x * b.x - a.y * b.y - a.z * b.z,
  };
}

export function clonePose(pose: ObstaclePose): ObstaclePose {
  return { position: { ...pose.position }, rotation: { ...pose.rotation } };
}

/** Authored transform of a descriptor, with defaults filled in. */
export function basePoseOf(descriptor: ObstacleDescriptor): ObstaclePose {
  return {
    position: { ...descriptor.transform.position },
    rotation: { ...(descriptor.transform.rotation ?? IDENTITY_ROTATION) },
  };
}

export function obstacleScaleOf(descriptor: ObstacleDescriptor): Vec3 {
  return { ...(descriptor.transform.scale ?? UNIT_SCALE) };
}

/** Pose of a moving obstacle at `elapsedSeconds`, relative to its authored base pose. */
export function motionPose(
  motion: MovingObstacle['motion'],
  base: ObstaclePose,
  elapsedSeconds: number,
): ObstaclePose {
  const phase = motion.phase ?? 0;
  const t = phase + motion.speed * elapsedSeconds;

  if (motion.kind === 'rotate') {
    return {
      position: { ...base.position },
      rotation: multiplyQuat(quatFromAxisAngle(motion.axis, t), base.rotation),
    };
  }

  const axis = normalizeAxis(motion.axis);
  const offset = (motion.distance ?? 0) * Math.sin(t);
  return {
    position: {
      x: base.position.x + axis.x * offset,
      y: base.position.y + axis.y * offset,
      z: base.position.z + axis.z * offset,
    },
    rotation: { ...base.rotation },
  };
}
