import * as THREE from 'three';
import type { ObstacleDescriptor } from '../courses/types';
import { OBSTACLE_CONFIG, obstacleColor } from './config';
import type { ObstacleVisualFactory, ObstacleVisualOptions } from './types';

const MIN_EXTENT = 0.01;

/** Asset-free low-poly visuals; every obstacle owns its geometry and material. */
export class BoxObstacleVisuals implements ObstacleVisualFactory {
  create(descriptor: ObstacleDescriptor, options: ObstacleVisualOptions): THREE.Mesh {
    const sizeX = Math.max(options.size.x, MIN_EXTENT);
    const sizeY = Math.max(options.size.y, MIN_EXTENT);
    const sizeZ = Math.max(options.size.z, MIN_EXTENT);
    const geometry = descriptor.type === 'pillar'
      ? new THREE.CylinderGeometry(Math.max(sizeX, sizeZ) / 2, Math.max(sizeX, sizeZ) / 2, sizeY, 12)
      : new THREE.BoxGeometry(sizeX, sizeY, sizeZ);

    const material = new THREE.MeshStandardMaterial({
      color: obstacleColor(descriptor),
      roughness: 0.75,
      metalness: 0.05,
      transparent: options.sensor,
      opacity: options.sensor ? OBSTACLE_CONFIG.hazardOpacity : 1,
      depthWrite: !options.sensor,
    });

    const mesh = new THREE.Mesh(geometry, material);
    mesh.name = `obstacle:${descriptor.id}`;
    mesh.castShadow = !options.sensor;
    mesh.receiveShadow = true;
    return mesh;
  }
}
