import type * as THREE from 'three';
import type { Vec3 } from '../contracts/math';
import type { ObstacleDescriptor } from '../courses/types';
import { OBSTACLE_CONFIG, isMovingObstacle } from './config';
import { basePoseOf, clonePose, motionPose, obstacleScaleOf } from './motion';
import type { ObstacleBody, ObstaclePose } from './types';

export interface DynamicObstacleOptions {
  visual?: THREE.Object3D | null;
  body?: ObstacleBody | null;
  parent?: THREE.Object3D | null;
}

/**
 * One obstacle instance: authored descriptor + optional visual + optional physics
 * body, driven by update(delta) and torn down exactly once by dispose().
 */
export class DynamicObstacle {
  readonly id: string;
  readonly descriptor: ObstacleDescriptor;
  readonly visual: THREE.Object3D | null;
  readonly body: ObstacleBody | null;
  readonly basePose: ObstaclePose;
  readonly scale: Vec3;

  private currentPose: ObstaclePose;
  private elapsed = 0;
  private enabledValue: boolean;
  private disposedValue = false;

  constructor(descriptor: ObstacleDescriptor, options: DynamicObstacleOptions = {}) {
    this.descriptor = descriptor;
    this.id = descriptor.id;
    this.visual = options.visual ?? null;
    this.body = options.body ?? null;
    this.basePose = basePoseOf(descriptor);
    this.scale = obstacleScaleOf(descriptor);
    this.currentPose = clonePose(this.basePose);
    this.enabledValue = descriptor.enabled ?? true;

    if (this.visual && options.parent) options.parent.add(this.visual);
    this.applyPose(this.currentPose);
    this.applyEnabled();
  }

  get pose(): ObstaclePose { return clonePose(this.currentPose); }
  get enabled(): boolean { return this.enabledValue; }
  get disposed(): boolean { return this.disposedValue; }
  get elapsedSeconds(): number { return this.elapsed; }
  get animated(): boolean { return isMovingObstacle(this.descriptor); }

  update(deltaSeconds: number): void {
    if (this.disposedValue || !this.enabledValue) return;
    if (!Number.isFinite(deltaSeconds) || deltaSeconds <= 0) return;
    const descriptor = this.descriptor;
    if (!isMovingObstacle(descriptor)) return;

    this.elapsed += Math.min(deltaSeconds, OBSTACLE_CONFIG.maxUpdateStep);
    this.applyPose(motionPose(descriptor.motion, this.basePose, this.elapsed));
  }

  setEnabled(enabled: boolean): void {
    if (this.disposedValue || this.enabledValue === enabled) return;
    this.enabledValue = enabled;
    this.applyEnabled();
  }

  /** Returns the obstacle to its authored pose and restarts its motion clock. */
  reset(): void {
    if (this.disposedValue) return;
    this.elapsed = 0;
    this.applyPose(this.basePose);
  }

  dispose(): void {
    if (this.disposedValue) return;
    this.disposedValue = true;
    this.body?.dispose();
    const visual = this.visual;
    if (!visual) return;
    visual.removeFromParent();
    disposeObject3D(visual);
  }

  private applyPose(pose: ObstaclePose): void {
    this.currentPose = clonePose(pose);
    const visual = this.visual;
    if (visual) {
      visual.position.set(pose.position.x, pose.position.y, pose.position.z);
      visual.quaternion.set(pose.rotation.x, pose.rotation.y, pose.rotation.z, pose.rotation.w);
      visual.scale.set(this.scale.x, this.scale.y, this.scale.z);
    }
    this.body?.setPose(this.currentPose);
  }

  private applyEnabled(): void {
    if (this.visual) this.visual.visible = this.enabledValue;
    this.body?.setEnabled(this.enabledValue);
  }
}

function disposeObject3D(root: THREE.Object3D): void {
  root.traverse((object: THREE.Object3D) => {
    const mesh = object as THREE.Mesh;
    if (!mesh.isMesh) return;
    mesh.geometry?.dispose();
    const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
    for (const material of materials) material?.dispose();
  });
}
