import type * as THREE from 'three';
import type { ObstacleDescriptor } from '../courses/types';
import { OBSTACLE_CONFIG, isHazardObstacle, isMovingObstacle, obstacleRestitution } from './config';
import { DynamicObstacle } from './DynamicObstacle';
import { basePoseOf } from './motion';
import { BoxObstacleVisuals } from './ObstacleVisuals';
import type { ObstacleBodyOptions, ObstaclePhysicsAdapter, ObstacleVisualFactory } from './types';

export interface ObstacleManagerOptions {
  /** Scene node the visuals are attached to, e.g. SceneManager.dynamicRoot. */
  parent?: THREE.Object3D | null;
  /** Omit or pass null to run without physics (headless tools, tests). */
  physics?: ObstaclePhysicsAdapter | null;
  /** Omit for the built-in low-poly visuals, null for no visuals at all. */
  visuals?: ObstacleVisualFactory | null;
}

export function obstacleBodyOptions(descriptor: ObstacleDescriptor): ObstacleBodyOptions {
  return {
    size: { ...descriptor.size },
    kinematic: isMovingObstacle(descriptor),
    sensor: isHazardObstacle(descriptor),
    friction: OBSTACLE_CONFIG.friction,
    restitution: obstacleRestitution(descriptor),
  };
}

/** Owns the obstacle set of the current hole: create, update, remove, tear down. */
export class ObstacleManager {
  private readonly obstacles = new Map<string, DynamicObstacle>();
  private readonly parent: THREE.Object3D | null;
  private readonly physics: ObstaclePhysicsAdapter | null;
  private readonly visuals: ObstacleVisualFactory | null;
  private disposedValue = false;

  constructor(options: ObstacleManagerOptions = {}) {
    this.parent = options.parent ?? null;
    this.physics = options.physics ?? null;
    this.visuals = options.visuals === undefined ? new BoxObstacleVisuals() : options.visuals;
  }

  get count(): number { return this.obstacles.size; }
  get disposed(): boolean { return this.disposedValue; }
  get ids(): string[] { return [...this.obstacles.keys()]; }

  list(): DynamicObstacle[] { return [...this.obstacles.values()]; }
  has(id: string): boolean { return this.obstacles.has(id); }
  get(id: string): DynamicObstacle | null { return this.obstacles.get(id) ?? null; }

  /** Replaces the whole set, disposing whatever was loaded before. */
  load(descriptors: readonly ObstacleDescriptor[]): DynamicObstacle[] {
    this.clear();
    return descriptors.map((descriptor) => this.add(descriptor));
  }

  add(descriptor: ObstacleDescriptor): DynamicObstacle {
    if (this.disposedValue) throw new Error('ObstacleManager is disposed');
    this.remove(descriptor.id);

    const options = obstacleBodyOptions(descriptor);
    const visual = this.visuals?.create(descriptor, { size: options.size, sensor: options.sensor }) ?? null;
    const body = this.physics?.createBody(descriptor, basePoseOf(descriptor), options) ?? null;
    const obstacle = new DynamicObstacle(descriptor, { visual, body, parent: this.parent });
    this.obstacles.set(obstacle.id, obstacle);
    return obstacle;
  }

  remove(id: string): boolean {
    const obstacle = this.obstacles.get(id);
    if (!obstacle) return false;
    this.obstacles.delete(id);
    obstacle.dispose();
    return true;
  }

  update(deltaSeconds: number): void {
    if (this.disposedValue) return;
    for (const obstacle of this.obstacles.values()) obstacle.update(deltaSeconds);
  }

  reset(): void {
    for (const obstacle of this.obstacles.values()) obstacle.reset();
  }

  clear(): void {
    for (const obstacle of this.obstacles.values()) obstacle.dispose();
    this.obstacles.clear();
  }

  dispose(): void {
    if (this.disposedValue) return;
    this.disposedValue = true;
    this.clear();
  }
}
