import RAPIER from '@dimforge/rapier3d-compat';
import type { ObstacleDescriptor } from '../courses/types';
import { CollisionLayers, collisionGroups } from '../physics/CollisionLayers';
import type { PhysicsWorld } from '../physics/PhysicsWorld';
import type { ObstacleBody, ObstacleBodyOptions, ObstaclePhysicsAdapter, ObstaclePose } from './types';

export const OBSTACLE_COLLISION_GROUPS = collisionGroups(CollisionLayers.OBSTACLE, CollisionLayers.BALL);
export const HAZARD_COLLISION_GROUPS = collisionGroups(CollisionLayers.SENSOR, CollisionLayers.BALL);

const MIN_HALF_EXTENT = 0.005;

class RapierObstacleBody implements ObstacleBody {
  private disposedValue = false;

  constructor(
    private readonly physics: PhysicsWorld,
    readonly rigidBody: RAPIER.RigidBody,
    readonly collider: RAPIER.Collider,
    private readonly kinematic: boolean,
  ) {}

  setPose(pose: ObstaclePose): void {
    if (this.disposedValue) return;
    if (this.kinematic) {
      this.rigidBody.setNextKinematicTranslation(pose.position);
      this.rigidBody.setNextKinematicRotation(pose.rotation);
      return;
    }
    this.rigidBody.setTranslation(pose.position, false);
    this.rigidBody.setRotation(pose.rotation, false);
  }

  setEnabled(enabled: boolean): void {
    if (this.disposedValue) return;
    this.collider.setEnabled(enabled);
  }

  dispose(): void {
    if (this.disposedValue) return;
    this.disposedValue = true;
    this.physics.world.removeCollider(this.collider, false);
    this.physics.world.removeRigidBody(this.rigidBody);
  }
}

/** Binds obstacles to Rapier: fixed bodies for static shapes, kinematic for moving ones. */
export class RapierObstaclePhysics implements ObstaclePhysicsAdapter {
  constructor(private readonly physics: PhysicsWorld) {}

  createBody(descriptor: ObstacleDescriptor, pose: ObstaclePose, options: ObstacleBodyOptions): ObstacleBody {
    const bodyDesc = (options.kinematic
      ? RAPIER.RigidBodyDesc.kinematicPositionBased()
      : RAPIER.RigidBodyDesc.fixed())
      .setTranslation(pose.position.x, pose.position.y, pose.position.z)
      .setRotation(pose.rotation);
    const rigidBody = this.physics.world.createRigidBody(bodyDesc);

    const colliderDesc = RAPIER.ColliderDesc.cuboid(
      Math.max(options.size.x / 2, MIN_HALF_EXTENT),
      Math.max(options.size.y / 2, MIN_HALF_EXTENT),
      Math.max(options.size.z / 2, MIN_HALF_EXTENT),
    )
      .setFriction(options.friction)
      .setRestitution(options.restitution)
      .setSensor(options.sensor)
      .setCollisionGroups(options.sensor ? HAZARD_COLLISION_GROUPS : OBSTACLE_COLLISION_GROUPS);
    const collider = this.physics.world.createCollider(colliderDesc, rigidBody);
    collider.setEnabled(descriptor.enabled ?? true);

    return new RapierObstacleBody(this.physics, rigidBody, collider, options.kinematic);
  }
}
